package com.vandorlabs.copier;

import com.vandorlabs.vehicle.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.Future;
import net.minecraft.entity.player.*;
import net.minecraft.nbt.*;
import net.minecraft.tileentity.TileEntity;
import net.minecraft.util.math.*;
import net.minecraft.world.*;
import net.minecraft.world.chunk.Chunk;

/** Exact-NBT inert inventories stay locked until their copy or rollback is durably checkpointed. */
public final class CopyTransactions {
    private static final Map<WorldServer,ArrayDeque<Work>> QUEUES=new IdentityHashMap<>();
    private static final Map<WorldServer,Map<Path,Hold>> HOLDS=new IdentityHashMap<>();
    private static final Set<WorldServer> LOADED=Collections.newSetFromMap(new IdentityHashMap<>());
    private static final ThreadLocal<Work> PREFLIGHT=new ThreadLocal<>();
    interface Fault {void check(String stage);}
    static Fault fault;
    private static void check(String stage){if(fault!=null&&System.getProperty("vandorlabs.reprolab")!=null)fault.check(stage);}
    private static final class Work {
        final CopyControllerTile owner;final EntityPlayerMP actor;final WorldServer world;final UUID id=UUID.randomUUID();
        CopyPlan plan;Hold hold;Map<BlockPos,TileEntity> prepared;Future<?> journal;boolean mutated;Exception failure;
        Work(CopyControllerTile owner,EntityPlayerMP actor){this.owner=owner;this.actor=actor;world=(WorldServer)owner.getWorld();}
    }
    private static final class Hold {
        final WorldServer world;final Path file;final NBTTagCompound record;final VehicleStructure target;final BlockPos origin,max,controller;final CopySupply supply;
        final Map<BlockPos,TileEntity> originals=new LinkedHashMap<>();TransferCheckpoint checkpoint;Future<?> completion;boolean checkpointReady,recovering;
        Hold(WorldServer world,Path file,NBTTagCompound record){this.world=world;this.file=file;this.record=record.copy();if(record.getInteger("Schema")!=1)throw new IllegalArgumentException("Unknown copy journal");target=VehicleStructure.readDisplay(record.getCompoundTag("Result"));origin=BlockPos.fromLong(record.getLong("TargetOrigin"));max=BlockPos.fromLong(record.getLong("TargetMax"));controller=BlockPos.fromLong(record.getLong("Controller"));supply=record.hasKey("Supply",10)?CopySupply.read(record.getCompoundTag("Supply")):null;if(max.getX()<origin.getX()||max.getY()<origin.getY()||max.getZ()<origin.getZ()||max.getX()-origin.getX()>15||max.getY()-origin.getY()>15||max.getZ()-origin.getZ()>15)throw new IllegalArgumentException("Invalid journal copy volume");}
        boolean protects(BlockPos p){if(p.equals(controller))return true;return inside(p,origin.add(-1,-1,-1),max.add(1,1,1))||supply!=null&&inside(p,supply.origin.add(-1,-1,-1),supply.origin.add((int)supply.before.bounds.maxX,(int)supply.before.bounds.maxY,(int)supply.before.bounds.maxZ));}
        boolean loaded(){if(!world.isAreaLoaded(origin,max,false))return false;if(supply!=null)for(VehicleStructure.Cell cell:supply.before.cells)if(!world.isBlockLoaded(supply.origin.add(cell.pos),false))return false;return true;}
        Set<Chunk> chunks(){Set<Chunk> chunks=new LinkedHashSet<>();for(VehicleStructure.Cell cell:target.cells)chunks.add(world.getChunkFromBlockCoords(origin.add(cell.pos)));if(supply!=null)for(VehicleStructure.Cell cell:supply.before.cells)chunks.add(world.getChunkFromBlockCoords(supply.origin.add(cell.pos)));for(BlockPos p:originals.keySet())if(world.isBlockLoaded(p,false))chunks.add(world.getChunkFromBlockCoords(p));if(world.isBlockLoaded(controller,false))chunks.add(world.getChunkFromBlockCoords(controller));return chunks;}
    }
    private CopyTransactions(){}
    private static Path directory(WorldServer world){return world.getSaveHandler().getWorldDirectory().toPath().resolve("data").resolve("vandorlabs-copies-"+world.provider.getDimension());}
    private static boolean inside(BlockPos p,BlockPos min,BlockPos max){return p.getX()>=min.getX()&&p.getY()>=min.getY()&&p.getZ()>=min.getZ()&&p.getX()<=max.getX()&&p.getY()<=max.getY()&&p.getZ()<=max.getZ();}
    private static boolean inside(BlockPos p,BlockPos[] box){return inside(p,box[0],box[1]);}
    public static boolean busy(CopyControllerTile owner){if(!(owner.getWorld() instanceof WorldServer))return false;ArrayDeque<Work> queue=QUEUES.get(owner.getWorld());if(queue!=null)for(Work work:queue)if(work.owner==owner)return true;Map<Path,Hold> holds=HOLDS.get(owner.getWorld());if(holds!=null)for(Hold hold:holds.values())if(hold.controller.equals(owner.getPos()))return true;return false;}
    public static void submit(CopyControllerTile owner,EntityPlayerMP actor)throws Exception{if(busy(owner))throw new IllegalArgumentException("A copy or recovery checkpoint is already in progress");if(actor==null||actor.world!=owner.getWorld()||actor.isDead||actor.isSpectator())throw new IllegalArgumentException("Remain in this dimension to authorize the copy");ArrayDeque<Work> queue=QUEUES.computeIfAbsent((WorldServer)owner.getWorld(),w->new ArrayDeque<>());if(queue.size()>=8)throw new IllegalArgumentException("Copy queue is full; try again");queue.add(new Work(owner,actor));owner.status("Preparing exact copy and materials");}
    public static boolean locked(World world,BlockPos p){if(world instanceof WorldServer&&!LOADED.contains(world)){load((WorldServer)world);if(!LOADED.contains(world))return true;}Map<Path,Hold> holds=HOLDS.get(world);if(holds!=null)for(Hold hold:holds.values())if(hold.protects(p))return true;ArrayDeque<Work> queue=QUEUES.get(world);if(queue!=null)for(Work work:queue){if(PREFLIGHT.get()==work)continue;if(p.equals(work.owner.getPos()))return true;if(p.equals(work.owner.chest())||work.owner.input!=null&&inside(p,CopyPlan.volume(work.owner.input,work.owner.height))||work.owner.output!=null&&inside(p,CopyPlan.volume(work.owner.output,work.owner.height)))return true;}return false;}
    private static void closeContainers(WorldServer world,Hold hold){for(EntityPlayer player:world.playerEntities)if(player.openContainer!=player.inventoryContainer&&!(player.openContainer instanceof CopyControllerContainer)&&(inside(player.getPosition(),hold.origin.add(-8,-8,-8),hold.max.add(8,8,8))||hold.supply!=null&&player.getDistanceSq(hold.supply.origin)<128))player.closeScreen();}
    private static void freeze(Hold hold,Chunk only){
        List<BlockPos> positions=new ArrayList<>();for(VehicleStructure.Cell cell:hold.target.cells)if(cell.hasTileData())positions.add(hold.origin.add(cell.pos));if(hold.supply!=null)for(VehicleStructure.Cell cell:hold.supply.before.cells)positions.add(hold.supply.origin.add(cell.pos));
        for(BlockPos p:positions){if(only!=null&&(p.getX()>>4)!=only.x||only!=null&&(p.getZ()>>4)!=only.z||!hold.world.isBlockLoaded(p,false))continue;TileEntity tile=hold.world.getTileEntity(p);if(tile==null||tile.isInvalid()||tile instanceof CopyFrozenTile)continue;hold.originals.putIfAbsent(p,tile);CopyWorld.freeze(hold.world,p);}
    }
    public static void load(WorldServer world){if(!LOADED.add(world))return;Path dir=directory(world);try{TransferJournalIO.barrier();}catch(Exception unavailable){LOADED.remove(world);com.vandorlabs.VandorLabs.logger.error("Copy journal disk worker unavailable; transfers remain locked",unavailable);return;}if(!Files.isDirectory(dir))return;try(java.nio.file.DirectoryStream<Path> files=Files.newDirectoryStream(dir,"*.nbt")){for(Path path:files)try{Hold hold=new Hold(world,path,read(path));HOLDS.computeIfAbsent(world,w->new LinkedHashMap<>()).put(path,hold);}catch(Exception invalid){com.vandorlabs.VandorLabs.logger.error("Copy recovery journal retained but unavailable: {}",path.getFileName(),invalid);}}catch(IOException invalid){com.vandorlabs.VandorLabs.logger.error("Copy recovery journals unavailable",invalid);}}
    public static void beforeTick(WorldServer world){load(world);Map<Path,Hold> holds=HOLDS.get(world);if(holds!=null)for(Hold hold:holds.values()){closeContainers(world,hold);freeze(hold,null);}}
    public static void chunkLoaded(Chunk chunk){if(!(chunk.getWorld() instanceof WorldServer))return;WorldServer world=(WorldServer)chunk.getWorld();load(world);Map<Path,Hold> holds=HOLDS.get(world);if(holds!=null)for(Hold hold:holds.values())freeze(hold,chunk);}
    private static NBTTagCompound record(Work work){NBTTagCompound tag=new NBTTagCompound();tag.setInteger("Schema",1);tag.setUniqueId("AuthorizedActor",work.actor.getUniqueID());tag.setLong("Controller",work.owner.getPos().toLong());tag.setUniqueId("ControllerKey",work.owner.key);tag.setLong("TargetOrigin",work.plan.targetOrigin.toLong());tag.setLong("TargetMax",work.plan.targetMax.toLong());tag.setTag("Result",work.plan.result.write());if(work.plan.supply!=null)tag.setTag("Supply",work.plan.supply.write());return tag;}
    static void save(Path path,NBTTagCompound tag)throws IOException{Files.createDirectories(path.getParent());Path temp=path.resolveSibling(path.getFileName()+".tmp");ByteArrayOutputStream bytes=new ByteArrayOutputStream();CompressedStreamTools.writeCompressed(tag,bytes);if(bytes.size()>16*1024*1024)throw new IOException("Copy journal exceeds 16 MiB");try(FileOutputStream stream=new FileOutputStream(temp.toFile())){stream.write(bytes.toByteArray());stream.getFD().sync();}Files.move(temp,path,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);com.vandorlabs.persistence.JournalFiles.syncDirectory(path.getParent());}
    static NBTTagCompound read(Path path)throws IOException{if(Files.size(path)>16*1024*1024)throw new IOException("Oversized copy journal");try(InputStream stream=Files.newInputStream(path)){return CompressedStreamTools.read(new DataInputStream(new java.util.zip.GZIPInputStream(stream)),new NBTSizeTracker(64L*1024*1024));}}
    private static void verify(Hold hold,boolean rollback){
        if(rollback){if(!CopyWorld.empty(hold.world,hold.target,hold.origin)||hold.supply!=null&&!hold.supply.before.matchesExact(hold.world,hold.supply.origin))throw new IllegalArgumentException("Rolled-back copy changed; recovery backup retained");}
        else if(!hold.target.matchesExact(hold.world,hold.origin)||hold.supply!=null&&!hold.supply.after.matchesExact(hold.world,hold.supply.origin))throw new IllegalArgumentException("Installed copy or material chest changed; recovery backup retained");
    }
    private static void publish(Hold hold){Set<BlockPos> positions=new LinkedHashSet<>(hold.originals.keySet());for(VehicleStructure.Cell cell:hold.target.cells)positions.add(hold.origin.add(cell.pos));if(hold.supply!=null)for(VehicleStructure.Cell cell:hold.supply.before.cells)positions.add(hold.supply.origin.add(cell.pos));for(BlockPos p:positions)if(hold.world.isBlockLoaded(p,false)&&hold.world.getTileEntity(p) instanceof CopyFrozenTile){CopyWorld.publish(hold.world,p);if(hold.record.hasUniqueId("AuthorizedActor"))com.vandorlabs.tiles.WorldActionAuthorization.grant(hold.world.getTileEntity(p),hold.record.getUniqueId("AuthorizedActor"));check("publish");}}
    private static void retire(Hold hold)throws Exception{if(hold.world.disableLevelSaving)throw new IOException("World saving is disabled; copy backup retained");if(!hold.checkpointReady){check("checkpoint");if(hold.checkpoint==null)hold.checkpoint=new TransferCheckpoint(hold.world,hold.chunks());if(!hold.checkpoint.step())return;hold.checkpoint=null;hold.checkpointReady=true;}
        if(hold.completion==null){check("journal-completion");boolean rollback=hold.record.getBoolean("RolledBack");if(hold.record.getInteger("Outcome")==0)verify(hold,rollback);hold.record.setInteger("Outcome",rollback?2:1);NBTTagCompound stable=hold.record.copy();hold.completion=TransferJournalIO.submit(()->save(hold.file,stable));return;}
        if(!hold.completion.isDone())return;try{hold.completion.get();}catch(Exception failure){hold.completion=null;throw failure;}
        publish(hold);Files.delete(hold.file);if(hold.checkpoint!=null)hold.checkpoint.close();Map<Path,Hold> map=HOLDS.get(hold.world);if(map!=null)map.remove(hold.file);CopyWorld.notify(hold.world,hold.target,hold.origin);if(hold.supply!=null)CopyWorld.notify(hold.world,hold.supply.before,hold.supply.origin);}
    public static void tick(WorldServer world){load(world);if(!LOADED.contains(world))return;ArrayDeque<Work> queue=QUEUES.get(world);if(queue==null||queue.isEmpty())return;Work work=queue.peek();if(!TransferCoordinator.acquire(world,work))return;
        try{
            if(work.hold==null){if(world.disableLevelSaving)throw new IllegalArgumentException("World saving is disabled");if(work.owner.isInvalid()||world.getTileEntity(work.owner.getPos())!=work.owner)throw new IllegalArgumentException("Copy Controller changed");PREFLIGHT.set(work);try{work.plan=CopyPlan.prepare(work.owner,work.actor);work.plan.validate(world,work.actor);}finally{PREFLIGHT.remove();}work.prepared=CopyWorld.prepare(world,work.plan.result,work.plan.targetOrigin);Path file=directory(world).resolve(work.id+".nbt");work.hold=new Hold(world,file,record(work));NBTTagCompound stable=work.hold.record.copy();work.journal=TransferJournalIO.submit(()->save(file,stable));work.owner.status("Writing recoverable copy journal");return;}
            if(!work.mutated){if(!work.journal.isDone())return;work.journal.get();if(world.disableLevelSaving||work.owner.isInvalid()||world.getTileEntity(work.owner.getPos())!=work.owner)throw new IllegalArgumentException("Copy Controller or world saving changed");PREFLIGHT.set(work);try{work.plan.validate(world,work.actor);}finally{PREFLIGHT.remove();}Path file=work.hold.file;HOLDS.computeIfAbsent(world,w->new LinkedHashMap<>()).put(file,work.hold);closeContainers(world,work.hold);
                try{work.mutated=true;if(work.plan.supply!=null)work.plan.supply.withdraw(world);check("withdraw");CopyWorld.install(world,work.plan.result,work.plan.targetOrigin,work.prepared,true);check("install");verify(work.hold,false);work.hold.record.setBoolean("Installed",true);save(file,work.hold.record);freeze(work.hold,null);work.owner.status("Copy installed; verifying saved chunks");}
                catch(Exception failure){work.failure=failure;rollback(world,work.hold.record,true);work.hold.record.setBoolean("RolledBack",true);save(file,work.hold.record);freeze(work.hold,null);work.owner.status("Copy rolled back; verifying saved chunks");}
                return;
            }
            verify(work.hold,work.hold.record.getBoolean("RolledBack"));retire(work.hold);if(Files.exists(work.hold.file))return;if(work.failure==null)work.owner.completed();else work.owner.failure(work.failure.getMessage());finish(queue,work);
        }catch(Exception failure){work.owner.failure((work.mutated?"Copy recovery backup retained: ":"")+failure.getMessage());if(!work.mutated&&work.hold!=null){try{Files.deleteIfExists(work.hold.file);}catch(IOException ignored){}Map<Path,Hold> holds=HOLDS.get(world);if(holds!=null)holds.remove(work.hold.file);}if(work.hold!=null&&work.mutated){if(work.hold.checkpoint!=null){work.hold.checkpoint.close();work.hold.checkpoint=null;}work.hold.recovering=false;freeze(work.hold,null);}finish(queue,work);}
    }
    private static void finish(ArrayDeque<Work> queue,Work work){TransferCoordinator.release(work.world,work);queue.remove();work.owner.changed();}
    static void rollback(WorldServer world,NBTTagCompound tag,boolean internal){VehicleStructure target=VehicleStructure.readDisplay(tag.getCompoundTag("Result"));BlockPos origin=BlockPos.fromLong(tag.getLong("TargetOrigin"));boolean installed=tag.getBoolean("Installed");if(installed?!target.matchesExact(world,origin):!CopyWorld.clearOrMatches(world,target,origin,internal))throw new IllegalArgumentException("Output changed; original copy backup retained");CopySupply supply=tag.hasKey("Supply",10)?CopySupply.read(tag.getCompoundTag("Supply")):null;if(supply!=null&&!supply.before.matchesExact(world,supply.origin)&&!supply.after.matchesExact(world,supply.origin))throw new IllegalArgumentException("Material chest changed; copy backup retained");CopyWorld.clear(world,target,origin);if(supply!=null)supply.refund(world);}
    public static void recover(WorldServer world){load(world);Map<Path,Hold> map=HOLDS.get(world);if(map==null||map.isEmpty())return;Set<Path> active=new HashSet<>();ArrayDeque<Work> queue=QUEUES.get(world);if(queue!=null)for(Work work:queue)if(work.hold!=null)active.add(work.hold.file);for(Hold hold:new ArrayList<>(map.values())){if(active.contains(hold.file)||hold.completion!=null&&!hold.completion.isDone()||!hold.loaded()||world.disableLevelSaving||!TransferCoordinator.acquire(world,hold))continue;try{freeze(hold,null);if(!hold.recovering){if(hold.record.getInteger("Outcome")==0&&!hold.record.getBoolean("RolledBack")){if(hold.checkpoint!=null){hold.checkpoint.close();hold.checkpoint=null;}hold.checkpointReady=false;hold.completion=null;rollback(world,hold.record,false);hold.record.setBoolean("RolledBack",true);save(hold.file,hold.record);}hold.recovering=true;}if(hold.record.getInteger("Outcome")==0)verify(hold,hold.record.getBoolean("RolledBack"));retire(hold);if(!Files.exists(hold.file)&&world.isBlockLoaded(hold.controller,false)&&world.getTileEntity(hold.controller) instanceof CopyControllerTile){CopyControllerTile owner=(CopyControllerTile)world.getTileEntity(hold.controller);owner.error="";owner.status("Recovery complete; ready to copy");}}catch(Exception blocked){if(hold.checkpoint!=null){hold.checkpoint.close();hold.checkpoint=null;}freeze(hold,null);if(world.isBlockLoaded(hold.controller,false)&&world.getTileEntity(hold.controller) instanceof CopyControllerTile)((CopyControllerTile)world.getTileEntity(hold.controller)).failure("Copy recovery remains locked: "+blocked.getMessage());}finally{TransferCoordinator.release(world,hold);}}}
    public static void unload(WorldServer world){ArrayDeque<Work> queue=QUEUES.remove(world);if(queue!=null)for(Work work:queue)TransferCoordinator.release(world,work);Map<Path,Hold> holds=HOLDS.remove(world);if(holds!=null)for(Hold hold:holds.values()){if(hold.checkpoint!=null)hold.checkpoint.close();TransferCoordinator.release(world,hold);}LOADED.remove(world);}
    static int pendingCount(WorldServer world){Map<Path,Hold> holds=HOLDS.get(world);return holds==null?0:holds.size();}
    public static void drainForChecks(WorldServer world)throws Exception{long deadline=System.nanoTime()+65_000_000_000L;while(QUEUES.containsKey(world)&&!QUEUES.get(world).isEmpty()&&System.nanoTime()<deadline){beforeTick(world);tick(world);Thread.sleep(50);}if(QUEUES.containsKey(world)&&!QUEUES.get(world).isEmpty())throw new IllegalStateException("Copy checkpoint did not finish");}
}
